'use strict';
(()=>{
 if(typeof HTMLDialogElement==='undefined')return;document.querySelectorAll('.gallery').forEach(gallery=>{
 const links=[...gallery.querySelectorAll('a')].filter(a=>a.querySelector('img'));if(!links.length)return;
 const hint=document.createElement('p');hint.className='gallery-hint';hint.textContent='Tocca una fotografia per ingrandirla. Puoi sfogliare la raccolta senza uscire dalla pagina.';gallery.before(hint);
 const dialog=document.createElement('dialog');dialog.className='album-lightbox';dialog.setAttribute('aria-label','Fotografia ingrandita');dialog.innerHTML='<div class="lightbox-toolbar"><button type="button" data-action="previous" aria-label="Fotografia precedente">←</button><output class="lightbox-count" aria-live="polite"></output><button type="button" data-action="next" aria-label="Fotografia successiva">→</button><button type="button" data-action="out" aria-label="Riduci immagine">−</button><button type="button" data-action="in" aria-label="Ingrandisci immagine">+</button><button type="button" data-action="fit">Adatta</button><button type="button" class="close-lightbox" data-action="close" aria-label="Chiudi immagine ingrandita">Chiudi ×</button></div><div class="lightbox-imagewrap"><img alt=""></div><div class="lightbox-caption"><p></p><a target="_blank" rel="noopener">Apri il file originale ↗</a></div>';
 document.body.append(dialog);const image=dialog.querySelector('img'),wrap=dialog.querySelector('.lightbox-imagewrap'),caption=dialog.querySelector('.lightbox-caption p');let current=0,zoom=1,restoreOverflow='';
 function size(){wrap.classList.toggle('is-zoomed',zoom>1);if(zoom===1){image.style.width='';image.style.height='';}else{const fit=Math.min((wrap.clientWidth-40)/image.naturalWidth,(wrap.clientHeight-40)/image.naturalHeight);image.style.width=Math.round(image.naturalWidth*fit*zoom)+'px';image.style.height='auto';}}
 function show(index){current=Math.max(0,Math.min(links.length-1,index));zoom=1;const a=links[current],img=a.querySelector('img'),text=a.closest('figure')?.querySelector('.photo-label, figcaption')?.textContent.trim()||'Fotografia dell’album';image.alt=text;image.onload=size;image.src=a.href;caption.textContent=text;dialog.querySelector('.lightbox-count').textContent=(current+1)+' / '+links.length;dialog.querySelector('.lightbox-caption a').href=a.href;dialog.querySelector('[data-action="previous"]').disabled=current===0;dialog.querySelector('[data-action="next"]').disabled=current===links.length-1;wrap.scrollTop=0;wrap.scrollLeft=0;size();}
 links.forEach((a,i)=>a.addEventListener('click',e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;e.preventDefault();show(i);restoreOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.showModal();size();}));
 dialog.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;switch(b.dataset.action){case 'previous':show(current-1);break;case 'next':show(current+1);break;case 'in':zoom=Math.min(5,zoom*1.5);size();break;case 'out':zoom=Math.max(1,zoom/1.5);size();break;case 'fit':zoom=1;size();break;case 'close':dialog.close();break;}});
 dialog.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();show(current+1);}if(e.key==='ArrowLeft'){e.preventDefault();show(current-1);}});dialog.addEventListener('close',()=>{document.body.style.overflow=restoreOverflow;links[current].focus({preventScroll:true});});window.addEventListener('resize',size);
});
})();
